--
-- Estructura de tabla para la tabla `devolutions`
--

CREATE TABLE `devolutions` (
  `id` bigint(20) UNSIGNED NOT NULL,
  `entity_id` bigint(20) UNSIGNED NOT NULL,
  `lottery_id` bigint(20) UNSIGNED NOT NULL,
  `seller_id` bigint(20) UNSIGNED DEFAULT NULL,
  `user_id` bigint(20) UNSIGNED NOT NULL,
  `total_participations` int(11) NOT NULL DEFAULT 0,
  `total_liquidation` decimal(12,2) DEFAULT NULL,
  `return_reason` text DEFAULT NULL,
  `devolution_date` date NOT NULL,
  `devolution_time` time NOT NULL,
  `status` enum('procesada','pendiente','cancelada') NOT NULL DEFAULT 'procesada',
  `notes` text DEFAULT NULL,
  `special_prize_settlement` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`special_prize_settlement`)),
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

