-- --------------------------------------------------------

--
-- Estructura de tabla para la tabla `lottery_types`
--

CREATE TABLE `lottery_types` (
  `id` bigint(20) UNSIGNED NOT NULL,
  `name` varchar(255) DEFAULT NULL,
  `identificador` varchar(2) DEFAULT NULL,
  `ticket_price` decimal(10,2) DEFAULT NULL,
  `series` int(11) NOT NULL DEFAULT 10 COMMENT 'Cantidad de series para el tipo de sorteo',
  `billetes_serie` int(11) NOT NULL DEFAULT 100000 COMMENT 'Billetes por cada serie',
  `prize_categories` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`prize_categories`)),
  `is_active` tinyint(1) NOT NULL DEFAULT 1,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

--
-- Volcado de datos para la tabla `lottery_types`
--

