--
-- Estructura de tabla para la tabla `participations`
--

CREATE TABLE `participations` (
  `id` bigint(20) UNSIGNED NOT NULL,
  `entity_id` bigint(20) UNSIGNED NOT NULL,
  `set_id` bigint(20) UNSIGNED NOT NULL,
  `design_format_id` bigint(20) UNSIGNED NOT NULL,
  `participation_number` int(11) NOT NULL,
  `participation_code` varchar(255) NOT NULL,
  `book_number` int(11) NOT NULL,
  `status` enum('disponible','reservada','vendida','devuelta','anulada','perdida','asignada','pagada','reserva_venta_digital') DEFAULT 'disponible',
  `seller_id` bigint(20) UNSIGNED DEFAULT NULL,
  `sale_date` date DEFAULT NULL,
  `sale_time` time DEFAULT NULL,
  `sale_amount` decimal(10,2) DEFAULT NULL,
  `payment_method` varchar(50) DEFAULT NULL,
  `buyer_name` varchar(255) DEFAULT NULL,
  `wallet_mode` varchar(20) DEFAULT NULL,
  `buyer_phone` varchar(255) DEFAULT NULL,
  `buyer_email` varchar(255) DEFAULT NULL,
  `buyer_nif` varchar(255) DEFAULT NULL,
  `collected_at` timestamp NULL DEFAULT NULL,
  `donated_at` timestamp NULL DEFAULT NULL,
  `return_date` date DEFAULT NULL,
  `return_time` time DEFAULT NULL,
  `return_reason` text DEFAULT NULL,
  `returned_by` bigint(20) UNSIGNED DEFAULT NULL,
  `cancellation_date` date DEFAULT NULL,
  `cancellation_reason` text DEFAULT NULL,
  `cancelled_by` bigint(20) UNSIGNED DEFAULT NULL,
  `notes` text DEFAULT NULL,
  `metadata` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`metadata`)),
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

